class Brand:
    """Smollan brand tokens. Use these instead of hard-coded values."""

    # -- colours (theme1.xml of the Core Template) ---------------------------
    DARK_BLUE = RGBColor(0x00, 0x28, 0x4E)   # primary brand, covers, headings
    BLUE = RGBColor(0x00, 0x50, 0x83)        # primary accent, table headers
    CYAN_BLUE = RGBColor(0x00, 0x79, 0xC0)   # accent 1, 2nd chart series
    BRIGHT_CYAN = RGBColor(0x00, 0xBB, 0xF0) # links, tertiary accent
    MID_BLUE = RGBColor(0x54, 0x9A, 0xD3)    # soft callouts, 4th series
    CHARCOAL = RGBColor(0x37, 0x46, 0x5B)    # third cover tone, body emphasis
    NEAR_BLACK = RGBColor(0x0E, 0x1D, 0x29)  # dark backgrounds
    GREEN = RGBColor(0x16, 0xB7, 0x95)       # FOCAL colour - one per slide
    LIME = RGBColor(0x8A, 0xC5, 0x46)        # positive deltas, callouts
    PALE = RGBColor(0xEF, 0xF2, 0xF6)        # section backgrounds, zebra rows
    GREY_BLUE = RGBColor(0xB4, 0xC3, 0xCE)   # dividers, low emphasis
    WHITE = RGBColor(0xFF, 0xFF, 0xFF)

    # Order used for chart series / repeated items (matches the packs' charts).
    SERIES = [BLUE, GREEN, CYAN_BLUE, BRIGHT_CYAN, CHARCOAL, LIME, MID_BLUE, DARK_BLUE]

    HEADING_FONT = "Montserrat"
    BODY_FONT = "Calibri"

    SLIDE_W = Inches(13.333)
    SLIDE_H = Inches(7.5)
    MARGIN = Inches(0.64)        # the packs' left/right content margin
    CONTENT_TOP = Inches(1.55)   # below a one-line heading + sub-heading
    CONTENT_BOTTOM = Inches(6.95)  # above the footer strip

    # Text the preflight check treats as "template text left behind".
    LEFTOVER_PATTERNS = [
        r"\[client", r"click to (edit|add|insert)", r"insert (your|intro|desc)",
        r"your (slide )?heading", r"heading goes here", r"sub-heading (goes )?here",
        r"\bxx\b", r"xxxx", r"lorem", r"�", r"edit tables in master",
        r"type bullet", r"add your", r"text goes here", r"name surname",
        r"title or designation",
    ]


# =============================================================================
# 2. LOW-LEVEL PACKAGE HELPERS (copying parts between / within presentations)
# =============================================================================
def _partname_template(partname: str) -> str:
    """'/ppt/charts/chart12.xml' -> '/ppt/charts/chart%d.xml'."""
    m = re.match(r"^(.*?)(\d*)(\.[A-Za-z0-9]+)$", partname)
    return f"{m.group(1)}%d{m.group(3).lower()}"


class PartCopier:
    """Deep-copies OPC parts (slides, layouts, charts, media...) into a package.

    redirect maps a source part to an existing destination part (e.g. a source
    layout -> its already-copied twin) so the graph is re-wired, not duplicated.
    """

    def __init__(self, dest_pkg):
        self.pkg = dest_pkg
        self.used = {str(p.partname) for p in dest_pkg.iter_parts()}
        self.memo: dict[int, Any] = {}
        self._images = None

    def next_partname(self, tmpl: str) -> PackURI:
        i = 1
        while (tmpl % i) in self.used:
            i += 1
        name = tmpl % i
        self.used.add(name)
        return PackURI(name)

    def copy(self, src, redirect: dict | None = None, skip_reltypes=(RT.NOTES_SLIDE,)):
        redirect = redirect or {}
        if id(src) in redirect:
            return redirect[id(src)]
        if id(src) in self.memo:
            return self.memo[id(src)]
        if isinstance(src, ImagePart) or str(src.partname).startswith("/ppt/media/"):
            if self._images is None:
                self._images = {hashlib.sha1(p.blob).hexdigest(): p for p in self.pkg.iter_parts()
                                if str(p.partname).startswith("/ppt/media/")}
            sha = hashlib.sha1(src.blob).hexdigest()
            if sha not in self._images:
                self._images[sha] = PartFactory(self.next_partname(_partname_template(str(src.partname))),
                                                src.content_type, self.pkg, src.blob)
            self.memo[id(src)] = self._images[sha]
            return self._images[sha]
        new = PartFactory(self.next_partname(_partname_template(str(src.partname))),
                          src.content_type, self.pkg, src.blob)
        self.memo[id(src)] = new
        for rId, rel in list(src.rels.items()):
            if rel.reltype in skip_reltypes:
                continue
            if rel.is_external:
                r = _Relationship(new.partname.baseURI, rId, rel.reltype, RTM.EXTERNAL, rel.target_ref)
            else:
                tgt = self.copy(rel.target_part, redirect, skip_reltypes)
                r = _Relationship(new.partname.baseURI, rId, rel.reltype, RTM.INTERNAL, tgt)
            new.rels._rels[rId] = r
        new.rels.__dict__.pop("_rels_by_reltype", None)
        return new


def _dedupe_partnames(pkg):
    """Give every part a unique name (python-pptx and PartCopier number independently)."""
    parts = list(pkg.iter_parts())
    used = {str(p.partname) for p in parts}
    seen = set()
    for p in parts:
        name = str(p.partname)
        if name in seen:
            tmpl, i = _partname_template(name), 1
            while (tmpl % i) in used:
                i += 1
            p.partname = PackURI(tmpl % i)
            used.add(tmpl % i)
        seen.add(str(p.partname))


def _strip_unused_rels(part, xml_el):
    """Drop relationships a slide no longer references (after removing shapes)."""
    xml = etree.tostring(xml_el).decode()
    for rId, rel in list(part.rels.items()):
        if rel.reltype in (RT.SLIDE_LAYOUT, RT.NOTES_SLIDE, RT.SLIDE_MASTER):
            continue
        if f'"{rId}"' not in xml:
            part.drop_rel(rId)


def _renumber_shape_ids(sptree_el):
    """Make every cNvPr id in a shape tree unique (PowerPoint repairs duplicates)."""
    used = set()
    nodes = [n for n in sptree_el.iter() if n.tag.endswith("}cNvPr")]
    nxt = max([int(n.get("id", "0")) for n in nodes] + [1]) + 1
    for n in nodes:
        i = int(n.get("id", "0"))
        if i in used or i == 0:
            n.set("id", str(nxt))
            i = nxt
            nxt += 1
        used.add(i)


def _add_slide_part(prs, slide_part):
    rId = prs.part.relate_to(slide_part, RT.SLIDE)
    prs.slides._sldIdLst._add_sldId(id=prs.slides._sldIdLst._next_id, rId=rId)
    return rId


def _remove_slide(prs, slide):
    lst = prs.slides._sldIdLst
    for sldId in list(lst):
        if prs.part.related_part(sldId.rId) is slide.part:
            prs.part.drop_rel(sldId.rId)
            lst.remove(sldId)
            return


# =============================================================================
# 3. TEXT FILLING (keeps the template's own fonts, sizes, colours, bullets)
# =============================================================================
def _txbody(obj):
    if hasattr(obj, "_tc"):                      # table cell
        return obj._tc.get_or_add_txBody()
    return obj.text_frame._txBody


def _as_rpr(el):
    if el is None:
        return None
    rpr = etree.Element(qn("a:rPr"))
    for k, v in el.attrib.items():
        rpr.set(k, v)
    for c in el:
        rpr.append(copy.deepcopy(c))
    return rpr


def _para_models(txbody):
    models = []
    for p in txbody.findall(qn("a:p")):
        pPr = p.find(qn("a:pPr"))
        r = p.find(qn("a:r"))
        rpr = r.find(qn("a:rPr")) if r is not None else None
        if rpr is None:
            rpr = _as_rpr(p.find(qn("a:endParaRPr")))
        has_text = r is not None and bool("".join(t.text or "" for t in p.iter(qn("a:t"))).strip())
        models.append((pPr, rpr, has_text))
    with_text = [m for m in models if m[2]]
    return [(m[0], m[1]) for m in (with_text or models)] or [(None, None)]


def _normalize_paragraphs(value) -> list[tuple[int, str]]:
    """str -> one paragraph; list -> one paragraph per item ('- ' prefix = level 1)."""
    if value is None:
        return []
    items = value if isinstance(value, (list, tuple)) else [value]
    out = []
    for it in items:
        it = str(it)
        lvl = 0
        while it.startswith("- "):
            lvl += 1
            it = it[2:]
        out.append((lvl, it))
    return out


def _segments(text):
    """Split a paragraph into runs: '**bold**' segments and '\\n' line breaks."""
    out = []
    for li, line in enumerate(text.split("\n")):
        if li:
            out.append(("", False, True))
        for part in re.split(r"(\*\*.+?\*\*)", line):
            if not part:
                continue
            if part.startswith("**") and part.endswith("**"):
                out.append((part[2:-2], True, False))
            else:
                out.append((part, False, False))
    return out or [("", False, False)]


def set_text(target, value):
    """Replace the text of a shape / placeholder / table cell, keeping template formatting.

    value: str (use '\\n' for a line break, '**bold**' for emphasis) or list[str]
    for several paragraphs/bullets ('- ' prefix indents one level).
    """
    txbody = _txbody(target)
    models = _para_models(txbody)
    by_level = {}
    for pPr, rpr in models:
        lvl = int(pPr.get("lvl", "0")) if pPr is not None else 0
        by_level.setdefault(lvl, (pPr, rpr))
    for p in txbody.findall(qn("a:p")):
        txbody.remove(p)
    paras = _normalize_paragraphs(value) or [(0, "")]
    for i, (lvl, text) in enumerate(paras):
        pPr, rpr = by_level.get(lvl) or models[min(i, len(models) - 1)]
        p = etree.SubElement(txbody, qn("a:p"))
        if pPr is not None:
            np_ = copy.deepcopy(pPr)
            if lvl:
                np_.set("lvl", str(lvl))
            p.append(np_)
        elif lvl:
            etree.SubElement(p, qn("a:pPr")).set("lvl", str(lvl))
        for seg, bold, is_break in _segments(text):
            if is_break:
                br = etree.SubElement(p, qn("a:br"))
                if rpr is not None:
                    br.append(copy.deepcopy(rpr))
                continue
            r = etree.SubElement(p, qn("a:r"))
            rp = copy.deepcopy(rpr) if rpr is not None else etree.Element(qn("a:rPr"))
            rp.set("lang", rp.get("lang", "en-GB"))
            if bold:
                rp.set("b", "1")
            r.append(rp)
            etree.SubElement(r, qn("a:t")).text = seg


def _plain(value) -> list[str]:
    return [t for _, t in _normalize_paragraphs(value)]


# =============================================================================
# 4. SHAPE LOOKUP / PHOTOS / VIDEO
# =============================================================================
def _iter_shapes(shapes):
    for sh in shapes:
        yield sh
        if sh.shape_type == 6:  # group
            yield from _iter_shapes(sh.shapes)


def _purge_alternate_content(slide, idx):
    """Remove mc:AlternateContent blocks (Office 2016 charts etc.) holding placeholder idx.

    python-pptx does not see shapes inside mc:AlternateContent, so they would otherwise
    survive underneath the content we add."""
    tree = slide._element.cSld.spTree
    for node in list(tree):
        if etree.QName(node).localname != "AlternateContent":
            continue
        for ph in node.iter(qn("p:ph")):
            if int(ph.get("idx", "0")) == idx:
                tree.remove(node)
                break


def _find_shape(slide, ref):
    """Resolve a slot reference: 'ph:<idx>' | 'id:<shape id>' | 'cell:<shape id>:<row>:<col>'."""
    kind, _, rest = ref.partition(":")
    if kind == "ph":
        idx = int(rest)
        for sh in slide.shapes:
            if sh.is_placeholder and sh.placeholder_format.idx == idx:
                return sh
        _purge_alternate_content(slide, idx)
        for lph in slide.slide_layout.placeholders:      # instantiate from the layout
            if lph.placeholder_format.idx == idx:
                slide.shapes.clone_placeholder(lph)
                for sh in slide.shapes:
                    if sh.is_placeholder and sh.placeholder_format.idx == idx:
                        return sh
        return None
    if kind == "id":
        sid = int(rest)
        for sh in _iter_shapes(slide.shapes):
            if sh.shape_id == sid:
                return sh
        return None
    if kind == "cell":
        sid, r, c = (int(x) for x in rest.split(":"))
        sh = _find_shape(slide, f"id:{sid}")
        return sh.table.cell(r, c) if sh is not None else None
    raise SmollanError(f"bad slot reference {ref!r}")


def _remove_shape(sh):
    """Remove a shape; if it sits inside mc:AlternateContent (e.g. Office 2016 charts), remove the whole block."""
    el = sh._element
    node = el
    while node.getparent() is not None and etree.QName(node.getparent()).localname in ("Choice", "Fallback", "AlternateContent"):
        node = node.getparent()
    node.getparent().remove(node)


def _crop_to_fill(pic, box_w, box_h):
    iw, ih = pic.image.size
    if not iw or not ih:
        return
    img_ratio, box_ratio = iw / ih, box_w / box_h
    if img_ratio > box_ratio:     # too wide -> crop left/right
        excess = 1 - box_ratio / img_ratio
        pic.crop_left = pic.crop_right = excess / 2
    else:
        excess = 1 - img_ratio / box_ratio
        pic.crop_top = pic.crop_bottom = excess / 2


def put_photo(slide, shape, path):
    """Fill a picture placeholder (or any shape's box) with an image, cropped to fill."""
    path = str(path)
    if not os.path.exists(path):
        raise SmollanError(f"photo not found: {path}")
    if shape.is_placeholder and hasattr(shape, "insert_picture"):
        return shape.insert_picture(path)
    x, y, w, h = shape.left, shape.top, shape.width, shape.height
    pic = slide.shapes.add_picture(path, x, y, w, h)
    _crop_to_fill(pic, w, h)
    _remove_shape(shape)
    return pic


def put_video(slide, shape, path, poster=None):
    x, y, w, h = shape.left, shape.top, shape.width, shape.height
    mov = slide.shapes.add_movie(str(path), x, y, w, h, poster_frame_image=poster, mime_type="video/mp4")
    _remove_shape(shape)
    return mov


# =============================================================================
# 5. CHARTS (native, editable; brand colours)
# =============================================================================
CHART_TYPES = {
    "column": XL_CHART_TYPE.COLUMN_CLUSTERED,
    "stacked_column": XL_CHART_TYPE.COLUMN_STACKED,
    "stacked_100": XL_CHART_TYPE.COLUMN_STACKED_100,
    "bar": XL_CHART_TYPE.BAR_CLUSTERED,
    "stacked_bar": XL_CHART_TYPE.BAR_STACKED,
    "stacked_bar_100": XL_CHART_TYPE.BAR_STACKED_100,
    "line": XL_CHART_TYPE.LINE_MARKERS,
    "line_plain": XL_CHART_TYPE.LINE,
    "pie": XL_CHART_TYPE.PIE,
    "doughnut": XL_CHART_TYPE.DOUGHNUT,
    "area": XL_CHART_TYPE.AREA,
    "stacked_area": XL_CHART_TYPE.AREA_STACKED,
    "waterfall": XL_CHART_TYPE.COLUMN_STACKED,   # emulated with an invisible base series
}
_FAMILY = {  # python-pptx chart_type names -> our type names
    "COLUMN_CLUSTERED": "column", "COLUMN_STACKED_100": "stacked_100", "COLUMN_STACKED": "stacked_column",
    "BAR_CLUSTERED": "bar", "BAR_STACKED_100": "stacked_bar_100", "BAR_STACKED": "stacked_bar",
    "LINE_MARKERS_STACKED": "line", "LINE_MARKERS": "line", "LINE": "line_plain", "PIE": "pie",
    "DOUGHNUT": "doughnut", "AREA_STACKED": "stacked_area", "AREA": "area",
}


def _chart_family(chart):
    try:
        name = str(chart.chart_type).split(" ")[0].split(".")[-1]
    except Exception:
        return None
    return _FAMILY.get(name)


def _waterfall_data(values, totals):
    base, up, down, tot = [], [], [], []
    running = 0
    for i, v in enumerate(values):
        if i in totals:
            t = running if v is None else v
            running = t
            base.append(0); up.append(0); down.append(0); tot.append(t)
        elif v >= 0:
            base.append(running); up.append(v); down.append(0); tot.append(0)
            running += v
        else:
            running += v
            base.append(running); up.append(0); down.append(-v); tot.append(0)
    return [("Base", base), ("Increase", up), ("Decrease", down), ("Total", tot)]


def _chart_data(spec):
    cats = spec.get("categories")
    series = spec.get("series")
    if not cats or not series:
        raise SmollanError('chart needs "categories" and "series", e.g. '
                           '{"type": "column", "categories": ["Q1", "Q2"], "series": {"2026": [1, 2]}}')
    if isinstance(series, (list, tuple)):
        series = {spec.get("series_name", "Series 1"): series}
    data = CategoryChartData(number_format=spec.get("number_format", "General"))
    data.categories = cats
    if spec.get("type") == "waterfall":
        vals = list(series.values())[0]
        totals = set(spec.get("totals", [len(vals) - 1]))
        for name, vals2 in _waterfall_data(vals, totals):
            data.add_series(name, vals2)
        return data
    for name, vals in series.items():
        if len(vals) != len(cats):
            raise SmollanError(f"chart series {name!r} has {len(vals)} values for {len(cats)} categories")
        data.add_series(name, vals)
    return data


def style_chart(chart, spec):
    """Apply Smollan styling to a newly created chart."""
    ctype = spec.get("type", "column")
    chart.font.size = Pt(10)
    chart.font.name = Brand.BODY_FONT
    chart.font.color.rgb = Brand.CHARCOAL
    plot = chart.plots[0]
    multi = len(list(plot.series)) > 1 or ctype in ("pie", "doughnut")
    chart.has_legend = multi and ctype != "waterfall"
    if chart.has_legend:
        chart.legend.position = XL_LEGEND_POSITION.BOTTOM
        chart.legend.include_in_layout = False
    if ctype in ("pie", "doughnut"):
        for i, pt in enumerate(plot.series[0].points):
            pt.format.fill.solid()
            pt.format.fill.fore_color.rgb = Brand.SERIES[i % len(Brand.SERIES)]
    else:
        colors = Brand.SERIES
        if ctype == "waterfall":
            colors = [None, Brand.GREEN, Brand.BRIGHT_CYAN, Brand.BLUE]
            plot.gap_width = 60
            plot.overlap = 100
        for i, s in enumerate(plot.series):
            col = colors[i % len(colors)]
            fmt = s.format
            if col is None:
                fmt.fill.background()
                fmt.line.fill.background()
                continue
            if ctype.startswith("line"):
                fmt.line.color.rgb = col
                fmt.line.width = Pt(2.25)
                s.smooth = False
            else:
                fmt.fill.solid()
                fmt.fill.fore_color.rgb = col
        try:
            va = chart.value_axis
            va.has_major_gridlines = True
            va.major_gridlines.format.line.color.rgb = Brand.PALE
            va.format.line.fill.background()
            chart.category_axis.format.line.color.rgb = Brand.GREY_BLUE
        except Exception:
            pass
    if ctype == "waterfall":
        fmt = spec.get("number_format", "#,##0")
        for i, s in enumerate(plot.series):
            if i == 0:
                continue                        # invisible base series: no labels
            dl = s.data_labels
            dl.show_value = True
            dl.font.size = Pt(9)
            dl.number_format = f"{fmt};-{fmt};;"  # hide zero labels
            dl.number_format_is_linked = False
            dl.font.color.rgb = Brand.WHITE if i == 3 else Brand.NEAR_BLACK
    elif spec.get("labels") or ctype in ("pie", "doughnut"):
        plot.has_data_labels = True
        dl = plot.data_labels
        dl.font.size = Pt(9)
        dl.number_format = spec.get("number_format", "General")
        dl.number_format_is_linked = False
    if spec.get("title"):
        chart.has_title = True
        chart.chart_title.text_frame.text = spec["title"]
        f = chart.chart_title.text_frame.paragraphs[0].runs[0].font
        f.size, f.bold = Pt(12), True
    else:
        chart.has_title = False


def put_chart(slide, shape, spec):
    """Fill a chart slot. Re-uses the template chart (and its styling) when the type matches."""
    if not isinstance(spec, dict):
        raise SmollanError("chart slot expects a dict spec")
    data = _chart_data(spec)
    want = spec.get("type")
    existing = shape.chart if getattr(shape, "has_chart", False) and shape.has_chart else None
    if existing is not None and (want is None or want == _chart_family(existing)):
        existing.replace_data(data)
        if spec.get("title") and existing.has_title:
            existing.chart_title.text_frame.text = spec["title"]
        return shape
    xl = CHART_TYPES.get(want or "column")
    if xl is None:
        raise SmollanError(f"unknown chart type {want!r}; use one of {sorted(CHART_TYPES)}")
    if shape.is_placeholder and hasattr(shape, "insert_chart") and existing is None:
        frame = shape.insert_chart(xl, data)
    else:
        x, y, w, h = shape.left, shape.top, shape.width, shape.height
        _remove_shape(shape)
        frame = slide.shapes.add_chart(xl, x, y, w, h, data)
    style_chart(frame.chart, {**spec, "type": want or "column"})
    return frame


# =============================================================================
# 6. TABLES (resize a styled template table, keep its look)
# =============================================================================
TICKS = ["", "✓", "✔", "", "●", "", ""]
CROSSES = ["", "✗", "✕", "×", ""]
_FILL_TAGS = ("noFill", "solidFill", "gradFill", "blipFill", "pattFill", "grpFill")


def _table_symbol(tbl, col, pool):
    """Find a symbol cell (tick / dot / cross) in a column; return a copy of its <a:r>."""
    for search_col in [col] + list(range(len(tbl.columns))):
        for row in tbl.rows:
            if search_col >= len(row.cells):
                continue
            cell = row.cells[search_col]
            t = cell.text.strip()
            if t and t in pool:
                r = cell._tc.find(".//" + qn("a:r"))
                if r is not None:
                    return copy.deepcopy(r)
    return None


def _has_merge(rows):
    for r in rows:
        for tc in r._tr.findall(qn("a:tc")):
            if tc.get("gridSpan") or tc.get("rowSpan") or tc.get("hMerge") or tc.get("vMerge"):
                return True
    return False


def _set_cell(cell, value, tick_run=None, cross_run=None):
    is_tick = value is True or (isinstance(value, str) and value.strip().lower() in ("tick", "yes", "✓"))
    is_cross = value is False or (isinstance(value, str) and value.strip().lower() in ("cross", "no", "✗"))
    if not (is_tick or is_cross):
        return set_text(cell, "" if value is None else (value if isinstance(value, list) else str(value)))
    run = tick_run if is_tick else cross_run
    if run is None:
        return set_text(cell, "✓" if is_tick else "")
    txbody = _txbody(cell)
    ps = txbody.findall(qn("a:p"))
    keep_ppr = ps[0].find(qn("a:pPr")) if ps else None
    for p in ps:
        txbody.remove(p)
    p = etree.SubElement(txbody, qn("a:p"))
    if keep_ppr is not None:
        p.append(copy.deepcopy(keep_ppr))
    p.append(copy.deepcopy(run))


def _set_tc_fill(cell, fill_el):
    """Set a table cell's fill (fill_el = <a:solidFill> etc., or None for no fill)."""
    tcpr = cell._tc.get_or_add_tcPr()
    for child in list(tcpr):
        if etree.QName(child).localname in _FILL_TAGS:
            tcpr.remove(child)
    new = copy.deepcopy(fill_el) if fill_el is not None else etree.Element(qn("a:noFill"))
    lns = [c for c in tcpr if etree.QName(c).localname.startswith("ln")]
    if lns:
        lns[-1].addnext(new)
    else:
        tcpr.insert(0, new)


def put_table(shape, spec, header_rows=1, footer_rows=0, fixed=False):
    """Fill a table slot.

    spec = {"header": [[...]] | [...], "rows": [[...], ...], "footer": [[...]]}
           or a plain list of rows (the first `header_rows` rows are the header).
    Cell values: str | list[str] (paragraphs) | True (tick/dot) | False (cross) | None.
    The table keeps its overall size; rows/columns are added by cloning template ones,
    so zebra striping, coloured row labels and symbols carry over.
    """
    if isinstance(spec, (list, tuple)):
        spec = {"header": list(spec[:header_rows]), "rows": list(spec[header_rows:])}
    header = spec.get("header") or []
    if header and not isinstance(header[0], (list, tuple)):
        header = [header]
    body = [list(r) for r in spec.get("rows", [])]
    footer = spec.get("footer") or []
    if footer and not isinstance(footer[0], (list, tuple)):
        footer = [footer]
    tbl = shape.table
    R, C = len(tbl.rows), len(tbl.columns)
    all_rows = header + body + footer
    if not all_rows:
        raise SmollanError("table needs at least one row")
    newC = max(len(r) for r in all_rows)
    tick_runs = [_table_symbol(tbl, c, TICKS) for c in range(C)]
    cross_runs = [_table_symbol(tbl, c, CROSSES) for c in range(C)]
    H, F = min(header_rows, R), min(footer_rows, max(R - header_rows, 0))
    if header and len(header) != H:
        raise SmollanError(f"this table preset has {H} header row(s); you passed {len(header)}")
    if footer and len(footer) != F:
        raise SmollanError(f"this table preset has {F} footer row(s); you passed {len(footer)}")
    n_body_tmpl = R - H - F
    if fixed and (newC != C or len(body) != n_body_tmpl):
        raise SmollanError(f"this table preset has a fixed structure: {n_body_tmpl} body rows x {C} columns "
                           f"(+{H} header, {F} footer rows). Pass exactly that, or use a 'tables.clean*' recipe.")
    # ---- columns
    if newC != C:
        if _has_merge(list(tbl.rows)):
            raise SmollanError(f"this table preset has merged cells, so its {C} columns are fixed. Pass {C} "
                               f"values per row, or use 'tables.clean' for free-form tables.")
        grid = tbl._tbl.tblGrid
        total_w = sum(int(g.get("w")) for g in grid.findall(qn("a:gridCol")))
        while len(grid.findall(qn("a:gridCol"))) < newC:
            grid.append(copy.deepcopy(grid.findall(qn("a:gridCol"))[-1]))
            for tr in tbl._tbl.findall(qn("a:tr")):
                tr.append(copy.deepcopy(tr.findall(qn("a:tc"))[-1]))
        while len(grid.findall(qn("a:gridCol"))) > newC:
            grid.remove(grid.findall(qn("a:gridCol"))[-1])
            for tr in tbl._tbl.findall(qn("a:tr")):
                tr.remove(tr.findall(qn("a:tc"))[-1])
        cols = grid.findall(qn("a:gridCol"))
        old = [int(g.get("w")) for g in cols]
        scale = total_w / sum(old)
        for g, w in zip(cols, old):
            g.set("w", str(int(w * scale)))
        tick_runs = (tick_runs + [tick_runs[-1]] * newC)[:newC]
        cross_runs = (cross_runs + [cross_runs[-1]] * newC)[:newC]
    # ---- body rows
    tr_els = tbl._tbl.findall(qn("a:tr"))
    body_els = tr_els[H:len(tr_els) - F]
    if len(body) != len(body_els):
        if body_els and _has_merge(list(tbl.rows)[H:R - F]):
            raise SmollanError(f"this table preset has merged body cells, so it holds exactly "
                               f"{len(body_els)} body rows.")
        tmpl_body = [copy.deepcopy(e) for e in (body_els or tr_els[-1:])]
        total_h = sum(int(e.get("h")) for e in body_els) or int(tr_els[-1].get("h"))
        anchor = tr_els[H - 1] if H else None
        for e in body_els:
            tbl._tbl.remove(e)
        new_h = max(int(total_h / max(len(body), 1)), int(Inches(0.22)))
        insert_after = anchor
        for i in range(len(body)):
            e = copy.deepcopy(tmpl_body[i % len(tmpl_body)])
            e.set("h", str(min(new_h, int(e.get("h")))))
            if insert_after is None:
                tbl._tbl.tblGrid.addnext(e)
            else:
                insert_after.addnext(e)
            insert_after = e
    # ---- write values
    rows = list(tbl.rows)
    data_rows = (header if header else [None] * H) + body + (footer if footer else [None] * F)
    for ri, row in enumerate(rows):
        if ri >= len(data_rows) or data_rows[ri] is None:
            continue
        vals = data_rows[ri]
        for ci, cell in enumerate(row.cells):
            if cell.is_spanned:
                continue
            v = vals[ci] if ci < len(vals) else ""
            _set_cell(cell, v, tick_runs[min(ci, len(tick_runs) - 1)], cross_runs[min(ci, len(cross_runs) - 1)])
    return shape


def put_gantt(shape, spec):
    """Gantt preset. spec = {"periods": ["1", "2", ...], "tasks": [{"label": "...", "start": 1, "end": 3}],
    "corner": "WEEK"}. start/end are 1-based period numbers (inclusive)."""
    periods, tasks = spec["periods"], spec["tasks"]
    tbl = shape.table
    fills = []
    for row in list(tbl.rows)[1:]:
        for cell in list(row.cells)[1:]:
            sf = cell._tc.find(qn("a:tcPr") + "/" + qn("a:solidFill"))
            if sf is not None:
                fills.append(copy.deepcopy(sf))
                break
    put_table(shape, {"header": [[spec.get("corner", "WEEK")] + list(periods)],
                      "rows": [[t["label"]] + [""] * len(periods) for t in tasks]})
    for ti, (t, row) in enumerate(zip(tasks, list(tbl.rows)[1:])):
        fill = fills[ti % len(fills)] if fills else None
        for pi, cell in enumerate(list(row.cells)[1:], start=1):
            _set_tc_fill(cell, fill if (fill is not None and t["start"] <= pi <= t["end"]) else None)
    return shape


# =============================================================================
# 7. ORG CHARTS (drawn from tree data, Smollan styling)
# =============================================================================
ORG_LEVEL_COLORS = [Brand.DARK_BLUE, Brand.GREEN, Brand.BLUE, Brand.CHARCOAL, Brand.CYAN_BLUE]


def _org_nodes(tree, depth=0, out=None):
    out = [] if out is None else out
    out.append((depth, tree))
    for c in tree.get("children") or []:
        _org_nodes(c, depth + 1, out)
    return out


def org_size(tree):
    return len(_org_nodes(tree))


def draw_org_chart(slide, x, y, w, h, tree, max_cols=8):
    """Draw an org chart inside a box (EMU). tree = {"name", "role", "photo"?, "children": [...]}.

    A manager whose reports are all leaves gets them STACKED underneath when the chart
    would otherwise be wider than `max_cols` boxes. Raises SmollanError when it cannot
    fit - then split the tree over two slides (top levels on one, each branch on its own).
    """
    nodes = _org_nodes(tree)
    if max(d for d, _ in nodes) > 4:
        raise SmollanError("org chart deeper than 5 levels - split it over several slides "
                           "(top structure on one slide, each department on its own).")

    def leaves_only(n):
        ch = n.get("children") or []
        return bool(ch) and all(not c.get("children") for c in ch)

    stack = set()

    def units(n):
        ch = n.get("children") or []
        if not ch or id(n) in stack:
            return 1
        return sum(units(c) for c in ch)

    candidates = sorted([n for d, n in nodes if d >= 1 and leaves_only(n)], key=lambda n: -len(n["children"]))
    while units(tree) > max_cols and candidates:
        stack.add(id(candidates.pop(0)))
    total_units = units(tree)
    if total_units > max_cols:
        raise SmollanError(f"org chart needs {total_units} columns (max {max_cols}). Split it: top levels on "
                           f"one slide, each branch on its own slide (pass the branch as the tree).")
    gap_x = int(Inches(0.15))
    box_w = int(min(Inches(2.6), (w - gap_x * (total_units - 1)) / total_units))
    box_h, stack_h, stack_gap = int(Inches(0.7)), int(Inches(0.5)), int(Inches(0.08))

    row_levels = 0

    def row_depth(n, d):
        nonlocal row_levels
        row_levels = max(row_levels, d)
        if id(n) not in stack:
            for c in n.get("children") or []:
                row_depth(c, d + 1)

    row_depth(tree, 0)
    max_stack = max([len(n["children"]) for d, n in nodes if id(n) in stack] + [0])
    stack_block = (int(Inches(0.1)) + max_stack * (stack_h + stack_gap)) if max_stack else 0
    free = h - (row_levels + 1) * box_h - stack_block
    if free < row_levels * Inches(0.25):
        raise SmollanError("org chart is too tall for the slide - split it over two slides, or remove a level.")
    gap_y = int(min(Inches(0.6), free / max(row_levels, 1))) if row_levels else 0
    used_w = total_units * box_w + (total_units - 1) * gap_x
    used_h = (row_levels + 1) * box_h + row_levels * gap_y + stack_block
    x0, y0 = x + int((w - used_w) / 2), y + int(max(h - used_h, 0) / 2)
    shapes = slide.shapes
    pos = {}

    def place(n, d, left_unit):
        u = units(n)
        cx = x0 + int((left_unit + u / 2) * (box_w + gap_x) - gap_x / 2)
        top = y0 + d * (box_h + gap_y)
        pos[id(n)] = (cx, top, d)
        if id(n) in stack:
            for i, c in enumerate(n.get("children") or []):
                pos[id(c)] = (cx, top + box_h + int(Inches(0.1)) + i * (stack_h + stack_gap), d + 1)
            return
        lu = left_unit
        for c in n.get("children") or []:
            place(c, d + 1, lu)
            lu += units(c)

    place(tree, 0, 0)

    def line(x1, y1, x2, y2):
        ln = shapes.add_connector(MSO_CONNECTOR.STRAIGHT, x1, y1, x2, y2)
        ln.line.color.rgb = Brand.GREY_BLUE
        ln.line.width = Pt(1)

    def box(n, cx, top, d, small=False):
        bw = box_w if not small else int(box_w * 0.9)
        bh = box_h if not small else stack_h
        left = int(cx - bw / 2)
        photo = n.get("photo")
        if photo:
            pic = shapes.add_picture(str(photo), left, top, bh, bh)
            _crop_to_fill(pic, bh, bh)
            left, bw = left + bh, bw - bh
        sp = shapes.add_shape(MSO_SHAPE.RECTANGLE, left, top, bw, bh)
        sp.fill.solid()
        sp.fill.fore_color.rgb = ORG_LEVEL_COLORS[min(d, len(ORG_LEVEL_COLORS) - 1)]
        sp.line.fill.background()
        sp.shadow.inherit = False
        tf = sp.text_frame
        tf.word_wrap = True
        tf.vertical_anchor = MSO_ANCHOR.MIDDLE
        tf.margin_left = tf.margin_right = Inches(0.05)
        tf.margin_top = tf.margin_bottom = Inches(0.02)
        p = tf.paragraphs[0]
        p.alignment = PP_ALIGN.CENTER
        r = p.add_run()
        r.text = str(n.get("name", "")).upper()
        r.font.size, r.font.bold = Pt(9 if not small else 8), True
        r.font.name, r.font.color.rgb = Brand.HEADING_FONT, Brand.WHITE
        if n.get("role"):
            p2 = tf.add_paragraph()
            p2.alignment = PP_ALIGN.CENTER
            r2 = p2.add_run()
            r2.text = str(n["role"])
            r2.font.size = Pt(8 if not small else 7)
            r2.font.name, r2.font.color.rgb = Brand.BODY_FONT, Brand.WHITE

    def draw(n):
        cx, top, d = pos[id(n)]
        kids = n.get("children") or []
        if kids and id(n) in stack:
            line(cx, top + box_h, cx, pos[id(kids[-1])][1] + int(Inches(0.05)))
            for c in kids:
                ccx, ctop, cd = pos[id(c)]
                box(c, ccx, ctop, cd, small=True)
        elif kids:
            mid = top + box_h + int(gap_y / 2)
            line(cx, top + box_h, cx, mid)
            xs = [pos[id(c)][0] for c in kids]
            if len(xs) > 1:
                line(min(xs), mid, max(xs), mid)
            for c in kids:
                line(pos[id(c)][0], mid, pos[id(c)][0], pos[id(c)][1])
                draw(c)
        box(n, cx, top, d)

    draw(tree)


