# <<< RECIPES


# =============================================================================
# 8. RECIPE LOOKUP, SEARCH AND DOCUMENTATION
# =============================================================================
def _all_recipes():
    return RECIPES


def resolve(recipe: str) -> str:
    """Accept a recipe id, a template key ('p13.s08') or an exact original layout name."""
    if recipe in RECIPES:
        return recipe
    for rid, r in RECIPES.items():
        if recipe == r["src"] or recipe == r.get("layout"):
            return rid
    close = [rid for rid in RECIPES if recipe.split(".")[0] in rid][:8]
    raise SmollanError(f"unknown recipe {recipe!r}. Try find('<what you want to show>'). "
                       f"Similar ids: {close or sorted(RECIPES)[:10]}")


_SYNONYMS = {
    "team": "org", "structure": "org", "hierarchy": "org", "people": "org", "organisation": "org",
    "organization": "org", "kpi": "kpis", "measure": "kpis", "measures": "kpis", "metric": "kpis",
    "scorecard": "kpis", "step": "process", "steps": "process", "phases": "process", "timeline": "process",
    "roadmap": "process", "methodology": "process", "number": "stats", "numbers": "stats", "percent": "stats",
    "percentage": "stats", "statistic": "stats", "statistics": "stats", "chart": "graphs", "graph": "graphs",
    "trend": "graphs", "data": "graphs", "quote": "feedback", "testimonial": "feedback", "survey": "feedback",
    "differentiators": "why", "unique": "why", "pillars": "why", "intro": "cover", "opening": "cover",
    "title": "cover", "section": "divider", "break": "divider", "end": "closing", "thanks": "thankyou",
    "thank": "thankyou", "screenshot": "devices", "app": "devices", "phone": "devices", "laptop": "devices",
    "dashboard": "devices", "list": "buckets", "things": "buckets", "points": "buckets", "diagram": "infographic",
    "framework": "infographic", "swot": "infographic", "venn": "infographic", "cycle": "infographic",
    "comparison": "tables", "matrix": "tables", "grid": "tables", "gantt": "tables", "table": "tables",
}
_NUMWORDS = {"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8}


def find(query: str, n: int = 8, show: bool = True):
    """Rank recipes for a plain-English need, e.g. find('3 statistics with photos')."""
    words = re.findall(r"[a-z0-9]+", query.lower())
    count = next((int(w) if w.isdigit() else _NUMWORDS[w] for w in words if w.isdigit() or w in _NUMWORDS), None)
    terms = set(words) | {_SYNONYMS[w] for w in words if w in _SYNONYMS}
    scored = []
    for rid, r in RECIPES.items():
        fields = [(r["category"], 5), (" ".join(r.get("tags", [])), 3), (r["title"], 3),
                  (r["summary"], 2), (r.get("use_when", ""), 2), (rid, 2)]
        s = 0.0
        for text, w in fields:
            toks = set(re.findall(r"[a-z0-9]+", text.lower()))
            s += w * len(terms & toks)
        if count is not None and r.get("items") and r["items"]["min"] <= count <= r["items"]["n"]:
            s += 6
        if s:
            scored.append((s, rid))
    scored.sort(key=lambda t: (-t[0], t[1]))
    hits = [rid for _, rid in scored[:n]]
    if show:
        for rid in hits:
            print(f"{rid:<28} {RECIPES[rid]['title']}")
    return hits


def alternatives(rid: str, count: int | None = None) -> list[str]:
    r = RECIPES[rid]
    out = []
    for oid, o in RECIPES.items():
        if oid == rid or o["category"] != r["category"]:
            continue
        if count is None or (o.get("items") and o["items"]["min"] <= count <= o["items"]["n"]):
            out.append(oid)
    return out


def _example_value(name, spec, kind=None):
    kind = kind or spec["kind"]
    if kind == "photo":
        return "path/to/photo.jpg"
    if kind == "chart":
        return {"type": "column", "categories": ["Q1", "Q2", "Q3"], "series": {"2026": [4.1, 5.2, 6.3]}}
    if kind == "table":
        return {"header": ["COLUMN A", "COLUMN B"], "rows": [["Row 1", "Value"], ["Row 2", "Value"]]}
    if kind == "gantt":
        return {"periods": ["1", "2", "3", "4"], "tasks": [{"label": "KICK-OFF", "start": 1, "end": 2}]}
    if kind == "org":
        return {"name": "Jane Doe", "role": "Account Director",
                "children": [{"name": "John Roe", "role": "Field Manager"}]}
    if kind == "video":
        return "path/to/video.mp4"
    if name in ("heading",):
        return "YOUR HEADING"
    if name == "value":
        return "87%"
    return f"{name.replace('_', ' ').capitalize()} text"


def example_call(rid: str) -> str:
    r = RECIPES[rid]
    lines = [f'deck.add("{rid}",']
    for name, spec in r["slots"].items():
        lines.append(f"    {name}={_example_value(name, spec)!r},")
    if r.get("items"):
        it = r["items"]
        one = {f: _example_value(f, s) for f, s in it["fields"].items()}
        lines.append(f"    items=[{one!r},  # x{it['n'] if it['min'] == it['n'] else str(it['min']) + '-' + str(it['n'])}")
        lines.append("           ...],")
    lines.append(")")
    return "\n".join(lines)


def _limit_text(spec):
    bits = []
    if spec.get("max_lines"):
        bits.append(f"max {spec['max_lines']} line{'s' if spec['max_lines'] > 1 else ''}")
    elif spec.get("cap"):
        bits.append(f"fits ~{spec['cap']} line{'s' if spec['cap'] > 1 else ''}")
    if spec.get("cpl") and spec["kind"] == "text":
        bits.append(f"~{spec['cpl']} chars/line")
    return ", ".join(bits)


def describe(rid: str) -> str:
    """Full human/agent-readable spec of one recipe."""
    rid = resolve(rid)
    r = RECIPES[rid]
    out = [f"{rid}  -  {r['title']}", "=" * (len(rid) + len(r['title']) + 5),
           f"Category : {r['category']}", f"Source   : {r['pack']} / layout '{r['layout']}' (template {r['src']})",
           "", r["summary"], "", f"USE WHEN : {r.get('use_when', '')}", f"AVOID    : {r.get('avoid_when', '')}"]
    if r.get("notes"):
        out += ["", "NOTES:"] + [f"  - {n}" for n in r["notes"]]
    out += ["", "SLOTS:"]
    for name, s in r["slots"].items():
        req = " (required)" if s.get("required") else ""
        out.append(f"  {name:<14} {s['kind']:<6} {_limit_text(s):<32} {s.get('hint', '')}{req}")
    if r.get("items"):
        it = r["items"]
        cnt = it["n"] if it["min"] == it["n"] else f"{it['min']}-{it['n']}"
        out += ["", f"ITEMS: exactly {cnt} item dicts in items=[...]" if it["min"] == it["n"]
                else f"ITEMS: {cnt} item dicts in items=[...] (unused blocks are removed)"]
        for f, s in it["fields"].items():
            out.append(f"  {f:<14} {s['kind']:<6} {_limit_text(s):<32} {s.get('hint', '')}")
    alts = alternatives(rid)
    if alts:
        out += ["", "ALTERNATIVES: " + ", ".join(alts[:10])]
    out += ["", "EXAMPLE:", example_call(rid)]
    return "\n".join(out)


def show(rid: str):
    print(describe(rid))


# =============================================================================
# 9. VALIDATION
# =============================================================================
def _est_lines(value, cpl):
    if not cpl:
        return 0
    total = 0
    for para in _plain(value):
        for seg in para.replace("**", "").split("\n"):
            total += max(1, -(-len(seg) // cpl))
    return total


def _check_text(rid, where, spec, value, errors):
    if spec["kind"] != "text" or value is None:
        return
    if not isinstance(value, (str, list, tuple)):
        errors.append(f"{where}: expected text (str or list of str), got {type(value).__name__}")
        return
    limit = spec.get("max_lines") or spec.get("cap")
    cpl = spec.get("cpl")
    if not limit or not cpl:
        return
    est = _est_lines(value, int(cpl * 1.1))
    if est > limit:
        errors.append(f"{where}: ~{est} lines but this slot holds {limit} (about {limit * cpl} characters). "
                      f"Shorten the copy - do not shrink the font.")


def validate(rid: str, content: dict) -> list[str]:
    r = RECIPES[rid]
    errors = []
    allowed = set(r["slots"]) | ({"items"} if r.get("items") else set())
    for k in content:
        if k not in allowed:
            errors.append(f"unknown slot {k!r} for {rid}; valid slots: {sorted(allowed)}")
    for name, spec in r["slots"].items():
        if spec.get("required") and content.get(name) in (None, "", []):
            errors.append(f"{rid}.{name} is required")
        _check_text(rid, f"{rid}.{name}", spec, content.get(name), errors)
    it = r.get("items")
    items = content.get("items")
    if it:
        if items is None and it.get("keep_default"):
            items = None
        elif items is None:
            items = []
    if it and items is not None:
        if not isinstance(items, (list, tuple)) or not all(isinstance(i, dict) for i in items):
            errors.append(f"{rid}.items must be a list of dicts with keys {list(it['fields'])}")
        elif not (it["min"] <= len(items) <= it["n"]):
            cnt = it["n"] if it["min"] == it["n"] else f"{it['min']}-{it['n']}"
            alts = alternatives(rid, len(items))
            hint = f" Recipes in '{r['category']}' that take {len(items)}: {alts}" if alts else \
                f" No '{r['category']}' recipe takes {len(items)} - split the content over two slides."
            errors.append(f"{rid} holds {cnt} items; you passed {len(items)}.{hint}")
        else:
            for i, item in enumerate(items):
                for k in item:
                    if k not in it["fields"]:
                        errors.append(f"{rid}.items[{i}]: unknown field {k!r}; fields: {list(it['fields'])}")
                for f, spec in it["fields"].items():
                    _check_text(rid, f"{rid}.items[{i}].{f}", spec, item.get(f), errors)
    if r.get("special") == "process" and items and len(items) > 8:
        errors.append("process slides hold max 8 steps - split across two slides or use infographic.cycle")
    return errors


# =============================================================================
# 10. DECK - the main API
# =============================================================================
class Deck:
    """Build a Smollan deck.

    Deck(title=..., presenter=..., date=..., subtitle=..., client=...,
         cover="cover.dark_blue", closing="closing", auto_cover=True, auto_closing=True)
      .add(recipe_id, **slots)   -> adds one slide (see describe(recipe_id) for slots)
      .save(path)                -> adds the closing slide, removes unused layouts, runs preflight
    """

    def __init__(self, title: str | None = None, presenter: str | None = None, date: str | None = None,
                 subtitle: str | None = None, client: str | None = None, cover: str = "cover.dark_blue",
                 closing: str = "closing", auto_cover: bool = True, auto_closing: bool = True,
                 master: str = MASTER_PATH):
        if not os.path.exists(master):
            raise SmollanError(f"{master} not found - run tools/build_master.py first")
        self.prs = Presentation(master)
        self._templates = {s._element.cSld.get("name"): s for s in self.prs.slides}
        self._n_templates = len(self.prs.slides)
        self._copier = PartCopier(self.prs.part.package)
        self.client = client
        self.closing = closing
        self.auto_closing = auto_closing
        self.recipes_used: list[str] = []
        self.log: list[str] = []
        self._saved = False
        if auto_cover:
            self.add_cover(cover, title=title, subtitle=subtitle, presenter=presenter, date=date)

    # -- covers / closing ----------------------------------------------------
    def add_cover(self, recipe="cover.dark_blue", title=None, subtitle=None, presenter=None, date=None, **extra):
        rid = resolve(recipe)
        slots = RECIPES[rid]["slots"]
        offered = {"heading": title, "subheading": subtitle, "presenter": presenter, "date": date, **extra}
        return self.add(rid, **{k: v for k, v in offered.items() if k in slots and v is not None})

    # -- core ------------------------------------------------------------------
    def add(self, recipe: str, **content):
        """Add one slide from a recipe. Raises SmollanError (with a fix) if content breaks a rule."""
        if self._saved:
            raise SmollanError("deck already saved - create a new Deck")
        rid = resolve(recipe)
        r = RECIPES[rid]
        errors = validate(rid, content)
        if errors:
            raise SmollanError("; ".join(errors))
        tmpl = self._templates[r["src"]]
        self._copier.memo = {}
        part = self._copier.copy(tmpl.part, redirect={id(tmpl.slide_layout.part): tmpl.slide_layout.part})
        _add_slide_part(self.prs, part)
        slide = self.prs.slides[-1]
        slide._element.cSld.set("name", rid)
        n_slide = len(self.prs.slides) - self._n_templates
        filled, empty_photos = set(), []
        for name, spec in r["slots"].items():
            val = content.get(name)
            if val is not None and val != "":
                self._fill(slide, spec, spec["ref"], val, rid)
                filled.add(spec["ref"])
            elif spec["kind"] == "photo":
                empty_photos.append(spec["ref"])
            elif spec.get("keep"):
                if spec.get("default"):          # Smollan's standard wording
                    self._fill(slide, spec, spec["ref"], spec["default"], rid)
                filled.add(spec["ref"])
        it = r.get("items")
        items = content.get("items") or []
        drop_refs = set()
        if it:
            keep_defaults = not items and it.get("keep_default")
            for f, spec in it["fields"].items():
                for i, ref in enumerate(spec["refs"]):
                    if ref is None:
                        continue
                    val = items[i].get(f) if i < len(items) else None
                    if val is not None and val != "":
                        self._fill(slide, spec, ref, val, rid)
                        filled.add(ref)
                    elif spec["kind"] == "photo":
                        empty_photos.append(ref)
                    elif keep_defaults:
                        filled.add(ref)
                    elif i >= len(items):
                        drop_refs.add(ref)
        for ref in self._all_refs(r) - filled:
            if ref in empty_photos and ref not in drop_refs:
                self._reset_photo(slide, ref)
                self.log.append(f"slide {n_slide} ({rid}): photo slot {ref} left empty")
                continue
            self._clear(slide, ref)
        for ref in drop_refs | set(r.get("remove", [])):
            self._clear(slide, ref)
        if self.client:
            _replace_client(slide, self.client)
        _renumber_shape_ids(slide._element.cSld.spTree)
        _strip_unused_rels(slide.part, slide._element)
        self.recipes_used.append(rid)
        return slide

    @staticmethod
    def _all_refs(r):
        refs = {s["ref"] for s in r["slots"].values()}
        if r.get("items"):
            for s in r["items"]["fields"].values():
                refs |= {x for x in s["refs"] if x}
        return refs

    def _clear(self, slide, ref):
        if ref.startswith("ph:"):
            _purge_alternate_content(slide, int(ref[3:]))
        if ref.startswith("cell:"):
            cell = _find_shape(slide, ref)
            if cell is not None:
                set_text(cell, "")
            return
        kind, _, rest = ref.partition(":")
        for sh in list(_iter_shapes(slide.shapes)):
            if (kind == "ph" and sh.is_placeholder and sh.placeholder_format.idx == int(rest)) or \
                    (kind == "id" and sh.shape_id == int(rest)):
                _remove_shape(sh)
                return

    def _reset_photo(self, slide, ref):
        """Turn a template photo into an empty picture placeholder."""
        sh = _find_shape(slide, ref)
        if sh is None:
            return None
        if sh.is_placeholder and sh._element.tag == qn("p:pic"):
            _remove_shape(sh)
            sh = _find_shape(slide, ref)       # re-cloned (empty) from the layout
        elif not sh.is_placeholder and sh.shape_type == 13:
            pass
        return sh

    def _fill(self, slide, spec, ref, value, rid):
        kind = spec["kind"]
        if kind == "photo":
            sh = self._reset_photo(slide, ref)
            if sh is None:
                raise SmollanError(f"{rid}: photo slot {ref} not found")
            put_photo(slide, sh, value)
            return
        target = _find_shape(slide, ref)
        if target is None:
            raise SmollanError(f"{rid}: slot {ref} not found on template (rebuild the master?)")
        if kind == "text":
            set_text(target, value)
        elif kind == "chart":
            put_chart(slide, target, value)
        elif kind == "table":
            opts = spec.get("table", {})
            put_table(target, value, opts.get("header_rows", 1), opts.get("footer_rows", 0), opts.get("fixed", False))
        elif kind == "gantt":
            put_gantt(target, value)
        elif kind == "org":
            x, y, w, h = target.left, target.top, target.width, target.height
            _remove_shape(target)
            draw_org_chart(slide, x, y, w, h, value)
        elif kind == "video":
            put_video(slide, target, value)
        else:
            raise SmollanError(f"unknown slot kind {kind}")

    # -- output ----------------------------------------------------------------
    def save(self, path: str, preflight: bool = True) -> list[str]:
        if self._saved:
            raise SmollanError("deck already saved")
        last_cat = RECIPES[self.recipes_used[-1]]["category"] if self.recipes_used else None
        if self.auto_closing and last_cat not in ("closing", "thankyou"):
            self.add(self.closing)
        for s in list(self.prs.slides)[:self._n_templates]:
            _remove_slide(self.prs, s)
        used = {id(s.slide_layout.part) for s in self.prs.slides}
        layouts = self.prs.slide_masters[0].slide_layouts
        for lay in list(layouts):
            if id(lay.part) not in used:
                layouts.remove(lay)
        _dedupe_partnames(self.prs.part.package)
        self.prs.save(path)
        self._saved = True
        issues = preflight_check(self.prs) + self.log if preflight else []
        if preflight:
            print(f"saved {path}: {len(self.prs.slides)} slides; preflight: "
                  f"{'clean' if not issues else str(len(issues)) + ' issue(s)'}")
            for i in issues:
                print("  -", i)
        return issues


def _replace_client(slide, client):
    """Swap '[Client]' / '[CLIENT]' / '[Client X]' tokens for the client name, keeping formatting."""
    rx = re.compile(r"\[client(?: x)?\]", re.I)
    for sh in _iter_shapes(slide.shapes):
        frames = []
        if sh.has_text_frame:
            frames.append(sh.text_frame)
        if getattr(sh, "has_table", False) and sh.has_table:
            frames += [c.text_frame for row in sh.table.rows for c in row.cells]
        for tf in frames:
            for t in tf._txBody.iter(qn("a:t")):
                if t.text and rx.search(t.text):
                    t.text = rx.sub(lambda m: client.upper() if m.group(0).isupper() else client, t.text)


def preflight_check(prs) -> list[str]:
    """Find template text left behind, mojibake and empty placeholders."""
    pat = re.compile("|".join(Brand.LEFTOVER_PATTERNS), re.I)
    issues = []
    for n, s in enumerate(prs.slides, 1):
        rid = s._element.cSld.get("name") or "?"
        for sh in _iter_shapes(s.shapes):
            texts = []
            if sh.has_text_frame:
                texts.append(sh.text_frame.text)
            if getattr(sh, "has_table", False) and sh.has_table:
                texts += [c.text for row in sh.table.rows for c in row.cells]
            for t in texts:
                m = pat.search(t or "")
                if m:
                    issues.append(f"slide {n} ({rid}): leftover template text {t.strip()[:60]!r}")
    return issues


# =============================================================================
# 11. PHOTO LIBRARY (opt-in)
# =============================================================================
class _Assets:
    """assets.photo('name') -> path;  assets.photos('retail') -> [(name, description)]"""

    def _index(self):
        p = os.path.join(PHOTO_DIR, "index.json")
        if not os.path.exists(p):
            return {}
        with open(p, encoding="utf-8") as f:
            return json.load(f)

    def photo(self, name: str) -> str:
        idx = self._index()
        if name not in idx:
            raise SmollanError(f"no photo {name!r}; see assets.photos()")
        return os.path.join(PHOTO_DIR, idx[name]["file"])

    def photos(self, tag: str | None = None, show: bool = True):
        out = [(k, v["description"]) for k, v in self._index().items()
               if tag is None or tag.lower() in (v["description"] + " " + " ".join(v.get("tags", []))).lower()]
        if show:
            for k, d in out:
                print(f"{k:<28} {d}")
        return out


assets = _Assets()


# =============================================================================
# 12. CATALOG + CLI
# =============================================================================
CATEGORY_ORDER = ["cover", "divider", "title", "closing", "thankyou", "stats", "kpis", "process",
                  "infographic", "buckets", "graphs", "tables", "org", "feedback", "devices", "why"]
CATEGORY_INFO = {
    "cover": "Opening slides. Core shape covers (3 colour tones) and photo-led covers (6 photo families).",
    "divider": "Section breaks between chapters of the deck.",
    "title": "Plain content slides: heading (+ sub-heading) and a body text area. The fallback for anything.",
    "closing": "The Smollan end slide (logo, contact line).",
    "thankyou": "Thank-you slides with a personal message and next steps.",
    "stats": "Big-number proof points: 1-5 statistics, with or without photos.",
    "kpis": "What we will measure: KPI grids, KPI tables and scorecards.",
    "process": "Step-by-step methods: 3 to 8 steps (hard ceiling 8 per slide).",
    "infographic": "Concept diagrams: triad, triangle, circular, pivot-point (Venn), loop, cycle, SWOT.",
    "buckets": "'Here are N things' grids: 4-8 text buckets, optionally with a photo per bucket.",
    "graphs": "Native, editable charts: 1 or 2 per slide, with intro, description or text columns.",
    "tables": "Styled tables: comparison grids, tick matrices, gantt, scenario tables (incl. Growth Teams styles).",
    "org": "Team structures: drawn from tree data, or bespoke fixed-shape org charts (with photos).",
    "feedback": "Client survey feedback: quote + survey bar chart + action-plan date.",
    "devices": "Screens on devices: laptop, browser, phone(s) and video frames for app/dashboard shots.",
    "why": "Why Smollan: 4 pillars and custom differentiator grids.",
}


def catalog(write: bool = True):
    """Regenerate CATALOG.md and catalog.json from RECIPES."""
    cats = {}
    for rid, r in RECIPES.items():
        cats.setdefault(r["category"], []).append(rid)
    md = ["# Smollan Design System - Slide Catalog", "",
          f"{len(RECIPES)} slide recipes across {len(cats)} categories. Every recipe is one on-brand slide "
          "that `smollan.py` fills with your content.", "",
          "**How to use:** pick a recipe below (or `find('what you want to show')`), check its slots with "
          "`show('<id>')`, then `deck.add('<id>', **slots)`. See the top of `smollan.py` for the full API.", "",
          "## Quick picker", "", "| I want to show... | Category | Start with |", "|---|---|---|"]
    picks = {
        "a title / opening slide": ("cover", "cover.dark_blue"), "a new section": ("divider", "divider.dark_blue"),
        "a heading and some text / bullets": ("title", "title.one_line_sub"),
        "1-5 headline numbers": ("stats", "stats.3"), "what we will measure": ("kpis", "kpis.6"),
        "a step-by-step method": ("process", "process.5"), "a concept / framework": ("infographic", "infographic.triad"),
        "N points / benefits / services": ("buckets", "buckets.6"), "a chart / trend": ("graphs", "graphs.1"),
        "a data table / comparison": ("tables", "tables.clean"), "a team structure": ("org", "org.tree"),
        "client survey results": ("feedback", "feedback.chart_quote"), "an app or dashboard screenshot": ("devices", "devices.laptop_large"),
        "why choose Smollan": ("why", "why.pillars"), "the end": ("closing", "closing"),
    }
    for need, (cat, rid) in picks.items():
        if rid in RECIPES:
            md.append(f"| {need} | {cat} | `{rid}` |")
    md.append("")
    for cat in sorted(cats, key=lambda c: CATEGORY_ORDER.index(c) if c in CATEGORY_ORDER else 99):
        md += [f"## {cat}", "", CATEGORY_INFO.get(cat, ""), ""]
        md += ["| id | what it is |", "|---|---|"]
        for rid in cats[cat]:
            md.append(f"| [`{rid}`](#{rid.replace('.', '')}) | {RECIPES[rid]['title']} |")
        md.append("")
        for rid in cats[cat]:
            r = RECIPES[rid]
            md += [f"### {rid}", ""]
            thumb = f"thumbnails/{rid}.png"
            if os.path.exists(os.path.join(HERE, thumb)):
                md += [f"![{rid}]({thumb})", ""]
            md += [f"**{r['title']}** - {r['summary']}", "",
                   f"- **Use when:** {r.get('use_when', '')}", f"- **Avoid when:** {r.get('avoid_when', '')}",
                   f"- **Source:** `{r['pack']}` -> layout `{r['layout']}`"]
            for n_ in r.get("notes", []):
                md.append(f"- **Note:** {n_}")
            md += ["", "| slot | kind | limit | what goes here |", "|---|---|---|---|"]
            for name, s in r["slots"].items():
                md.append(f"| `{name}` | {s['kind']} | {_limit_text(s)} | {s.get('hint', '')} |")
            if r.get("items"):
                it = r["items"]
                cnt = it["n"] if it["min"] == it["n"] else f"{it['min']}-{it['n']}"
                for f, s in it["fields"].items():
                    md.append(f"| `items[{cnt}].{f}` | {s['kind']} | {_limit_text(s)} | {s.get('hint', '')} |")
            md += ["", "```python", example_call(rid), "```", ""]
    if write:
        with open(os.path.join(HERE, "CATALOG.md"), "w", encoding="utf-8") as f:
            f.write("\n".join(md))
        with open(os.path.join(HERE, "catalog.json"), "w", encoding="utf-8") as f:
            json.dump({"categories": CATEGORY_INFO, "recipes": RECIPES}, f, indent=1, ensure_ascii=False)
    return "\n".join(md)


def _cli(argv):
    if not argv or argv[0] in ("-h", "--help", "help"):
        print(__doc__)
        return
    cmd, rest = argv[0], argv[1:]
    if cmd == "list":
        cat = rest[0] if rest else None
        for rid, r in RECIPES.items():
            if cat is None or r["category"] == cat:
                print(f"{rid:<30} {r['title']}")
    elif cmd == "show":
        show(rest[0])
    elif cmd == "find":
        find(" ".join(rest))
    elif cmd == "catalog":
        catalog()
        print("wrote CATALOG.md and catalog.json")
    elif cmd == "photos":
        assets.photos(rest[0] if rest else None)
    else:
        print(f"unknown command {cmd!r}; use list | show <id> | find <words> | catalog | photos [tag]")


if __name__ == "__main__":
    _cli(sys.argv[1:])
